// The committed world and DP keys keep the parent's canonical representation A.
struct LazyTrialBoard {
    array<Word,MV> colors{};
    array<uint8_t,MV> meta{};
    static constexpr int reversed_bit=16;
    struct Tower {
        Word bits;
        uint8_t meta;
        [[gnu::always_inline]] int height() const {return meta&15;}
        [[gnu::always_inline]] bool reversed() const {return meta&reversed_bit;}
        [[gnu::always_inline]] static Word reverse_bits(Word x,int h) {
            x=((x>>4)&0x0f0f0f0fu)|((x&0x0f0f0f0fu)<<4);
            return uint64_t(__builtin_bswap32(x))>>(4*(8-h));
        }
        [[gnu::always_inline]] Tower take_top(int n,int h) {
            int k=h-n;
