        }
        [[gnu::always_inline]] void append_top(Tower packet,int g,int n) {
            if(!g) {*this=packet;return;}
            if(reversed()!=packet.reversed()) packet.bits=reverse_bits(packet.bits,n);
            if(reversed()) bits=Word(uint64_t(bits)<<(4*n))|packet.bits;
            else bits|=packet.bits<<(4*g);
