// Incoming bit (direction * 8 + distance - 1) names a launch cell.
// Heights alone determine whether a background tower can launch one item;
// keeping this index avoids testing the same unreachable rays each layer.
struct IncomingLaunches {
    array<uint32_t,MV> mask{};
    void update(int p,int before,int after) {
        int old_reach=before==8?0:before+1;
